def area_retangulo(base, altura):
    return base * altura

def perimetro_retangulo(base, altura):
    return 2 * (base + altura)

largura = 5
comprimento = 8

area = area_retangulo(largura, comprimento)
perimetro = perimetro_retangulo(largura, comprimento)

print("Area:", area)
print("Perimetro:", perimetro)

fatorial:
def fatorial(n):
    if n == 0:
        return 1
    return n * fatorial(n - 1)

print(fatorial(5))

fibonacci:
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

for i in range(7):
    print("fib(" + str(i) + ") =", fibonacci(i))

