classe:
class ContaBancaria:
    def __init__(self, titular, saldo):
        self.titular = titular
        self.saldo = saldo

    def depositar(self, valor):
        self.saldo = self.saldo + valor

    def sacar(self, valor):
        if valor <= self.saldo:
            self.saldo = self.saldo - valor
        else:
            print("Saldo insuficiente")

conta = ContaBancaria("Ana", 100)
conta.depositar(50)
conta.sacar(30)
print(conta.titular, "tem saldo de", conta.saldo)

try_except:
valores = ["10", "abc", "0", "7"]

for texto in valores:
    try:
        numero = int(texto)
        resultado = 100 / numero
        print(texto, "->", resultado)
    except ValueError:
        print(texto, "-> nao e um numero valido")
    except ZeroDivisionError:
        print(texto, "-> nao e possivel dividir por zero")

bubble_sort:
lista = [5, 3, 8, 1, 2]
n = len(lista)
for i in range(n):
    for j in range(0, n - i - 1):
        if lista[j] > lista[j + 1]:
            lista[j], lista[j + 1] = lista[j + 1], lista[j]
print("Ordenada:", lista)
